      if (typed_array->IsNull(i)) {
        auto status = (*column_indexer)->insert_null(doc_count);
        if (!status.ok()) {
          LOG_ERROR("Failed to insert null value to indexer for doc %zu: %s",
                    (size_t)doc_count, status.message().c_str());
